HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>DHA Phase 8 Property Assistant</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">\n<script src="https://cdn.jsdelivr.net/npm/marked@12.0.2/marked.min.js"></script>\n<script src="https://cdn.jsdelivr.net/npm/dompurify@3.1.6/dist/purify.min.js"></script>\n<style>\n:root{\n  --bg:#eef1ee; --panel:#ffffff; --ink:#15201b; --muted:#5d6b64;\n  --line:#d6ddd8; --green:#1f5a44; --green-dark:#12372a; --brass:#a67c2e; --user:#12372a;\n}\n@media (prefers-color-scheme:dark){\n  :root{--bg:#0f1713; --panel:#17211c; --ink:#e8efe9; --muted:#9baba2;\n  --line:#2a3a32; --green:#5fb08e; --green-dark:#0b120f; --brass:#d1a54a; --user:#1f5a44;}\n}\n*{box-sizing:border-box}\nhtml,body{height:100%;margin:0}\nbody{font-family:\'Schibsted Grotesk\',system-ui,sans-serif;background:var(--bg);color:var(--ink);\n  display:grid;grid-template-columns:300px 1fr;line-height:1.55}\naside{background:var(--green-dark);color:#e8efe9;padding:32px 24px;display:flex;flex-direction:column;gap:28px;overflow-y:auto}\naside h1{font-size:1.55rem;line-height:1.15;margin:0;font-weight:700;letter-spacing:-.01em}\naside h1 span{display:block;color:var(--brass);font-weight:500;font-size:1rem;margin-top:8px;letter-spacing:0}\naside p{margin:0;color:#a9bbb1;font-size:.9rem}\n.prompts{display:flex;flex-direction:column;gap:8px}\n.prompts button{all:unset;cursor:pointer;padding:10px 12px;border:1px solid #2f4b3e;border-radius:6px;font-size:.88rem;color:#e8efe9}\n.prompts button:hover{background:#1b3a2d;border-color:var(--brass)}\n.prompts button:focus-visible,#send:focus-visible,textarea:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\nmain{display:flex;flex-direction:column;height:100vh;min-width:0}\n#log{flex:1;overflow-y:auto;padding:28px clamp(16px,5vw,64px);display:flex;flex-direction:column;gap:18px}\n.msg{max-width:min(820px,100%);flex:none}\n.msg.user{align-self:flex-end;background:var(--user);color:#fff;padding:10px 16px;border-radius:14px 14px 2px 14px;white-space:pre-wrap}\n.msg.bot{align-self:flex-start;background:var(--panel);border:1px solid var(--line);padding:14px 18px;border-radius:2px 14px 14px 14px;overflow-y:visible;overflow-x:auto;min-height:min-content}\n.msg.bot>:first-child{margin-top:0}.msg.bot>:last-child{margin-bottom:0}\n.msg.bot table{border-collapse:collapse;margin:10px 0;font-size:.88rem;min-width:100%}\n.msg.bot th,.msg.bot td{border:1px solid var(--line);padding:6px 10px;text-align:left}\n.msg.bot th{background:color-mix(in srgb,var(--green) 12%,transparent)}\n.tag{display:block;font-size:.75rem;color:var(--muted);margin-top:10px}\n.empty{margin:auto;text-align:center;color:var(--muted);max-width:360px}\n.empty b{display:block;color:var(--ink);font-size:1.2rem;margin-bottom:6px}\n.dots span{display:inline-block;width:6px;height:6px;margin-right:4px;border-radius:50%;background:var(--muted);animation:b 1s infinite}\n.dots span:nth-child(2){animation-delay:.15s}.dots span:nth-child(3){animation-delay:.3s}\n@keyframes b{0%,80%,100%{opacity:.25}40%{opacity:1}}\nform{display:flex;gap:10px;padding:14px clamp(16px,5vw,64px) 20px;border-top:1px solid var(--line);background:var(--panel)}\ntextarea{flex:1;resize:none;font:inherit;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:10px 12px;max-height:140px}\n#send{font:inherit;font-weight:500;background:var(--green);color:#fff;border:0;border-radius:8px;padding:0 22px;cursor:pointer}\n#send:disabled{opacity:.5;cursor:default}\n@media(max-width:800px){\n  body{grid-template-columns:1fr;grid-template-rows:auto 1fr}\n  aside{padding:16px;gap:12px}\n  aside p{display:none}\n  .prompts{flex-direction:row;overflow-x:auto}\n  .prompts button{white-space:nowrap}\n  main{height:auto;min-height:0;overflow:hidden}\n  body{height:100dvh}\n}\n@media(prefers-reduced-motion:reduce){.dots span{animation:none}}\n</style>\n</head>\n<body>\n<aside>\n  <h1>DHA Lahore Phase 8<span>Property Assistant</span></h1>\n  <p>Live plot listings, price ranges and block statistics, plus answers on land units, file types and transfer costs.</p>\n  <div class="prompts" id="prompts">\n    <button>How many listings are there in total?</button>\n    <button>Show 1 Kanal plots in Block W under 5 Crore</button>\n    <button>Block-wise listing breakdown</button>\n    <button>Commercial vs residential prices</button>\n    <button>How many sq ft is 1 Kanal?</button>\n  </div>\n</aside>\n<main>\n  <div id="log" aria-live="polite">\n    <div class="empty" id="empty"><b>Ask about a plot</b>Try a block, size and budget, for example "10 Marla in Block A under 2 Crore".</div>\n  </div>\n  <form id="form">\n    <textarea id="input" rows="1" placeholder="Ask about plots, prices or DHA procedures" aria-label="Message"></textarea>\n    <button id="send" type="submit">Send</button>\n  </form>\n</main>\n<script>\nconst log = document.getElementById(\'log\'), input = document.getElementById(\'input\'),\n      send = document.getElementById(\'send\'), form = document.getElementById(\'form\');\nlet messages = [];\n\nfunction add(role, html, text) {\n  document.getElementById(\'empty\')?.remove();\n  const d = document.createElement(\'div\');\n  d.className = \'msg \' + role;\n  if (html) d.innerHTML = html; else d.textContent = text;\n  log.appendChild(d); log.scrollTop = log.scrollHeight;\n  return d;\n}\n\nasync function ask(text) {\n  text = text.trim(); if (!text) return;\n  input.value = \'\'; input.style.height = \'auto\';\n  send.disabled = true;\n  messages.push({role:\'user\', content:text});\n  add(\'user\', null, text);\n  const wait = add(\'bot\', \'<span class="dots"><span></span><span></span><span></span></span>\');\n  try {\n    const r = await fetch(\'/api/chat\', {method:\'POST\', headers:{\'Content-Type\':\'application/json\'},\n      body: JSON.stringify({messages})});\n    const raw = await r.text(); let data = {}; try { data = JSON.parse(raw); } catch (_) { data = {detail: r.ok ? \'Unreadable reply from server\' : \'The server took too long or hit an error\'}; }\n    if (!r.ok) throw new Error(data.detail || \'Request failed\');\n    messages.push({role:\'assistant\', content:data.reply});\n    const html = DOMPurify.sanitize(marked.parse(data.reply));\n    wait.innerHTML = html;\n  } catch (e) {\n    messages.pop();\n    wait.textContent = /try again/i.test(e.message) ? e.message : e.message + \' Please send your message again.\';\n  }\n  send.disabled = false; input.focus(); log.scrollTop = log.scrollHeight;\n}\n\nform.addEventListener(\'submit\', e => { e.preventDefault(); ask(input.value); });\ninput.addEventListener(\'keydown\', e => { if (e.key === \'Enter\' && !e.shiftKey) { e.preventDefault(); form.requestSubmit(); } });\ninput.addEventListener(\'input\', () => { input.style.height = \'auto\'; input.style.height = input.scrollHeight + \'px\'; });\ndocument.getElementById(\'prompts\').addEventListener(\'click\', e => { if (e.target.tagName === \'BUTTON\') ask(e.target.textContent); });\n</script>\n</body>\n</html>\n'
